CREATE TABLE projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT NOT NULL, name VARCHAR(80) NOT NULL, description VARCHAR(1000), color VARCHAR(7) NOT NULL, archived BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL);
CREATE INDEX projects_owner ON projects(owner_id);
CREATE TABLE tasks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(180) NOT NULL, description VARCHAR(10000), status VARCHAR(24) NOT NULL, priority VARCHAR(24) NOT NULL, due_date DATE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, assigned_user_id BIGINT NOT NULL, project_id BIGINT REFERENCES projects(id), version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX tasks_owner ON tasks(assigned_user_id,created_at);
CREATE INDEX tasks_project ON tasks(project_id);
CREATE TABLE task_labels (task_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, label VARCHAR(30));
CREATE TABLE task_checklist (task_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, position INTEGER NOT NULL, item_id VARCHAR(64), item_title VARCHAR(200), completed BOOLEAN NOT NULL, PRIMARY KEY(task_id,position));
CREATE TABLE task_comments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, author VARCHAR(80) NOT NULL, body VARCHAR(2000) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE INDEX comments_task ON task_comments(task_id,created_at);
CREATE TABLE activity (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT NOT NULL, action VARCHAR(240) NOT NULL, subject VARCHAR(180), task_id BIGINT, created_at TIMESTAMP NOT NULL);
CREATE INDEX activity_owner ON activity(owner_id,created_at);
